import { useState, useEffect } from 'react';
import {
  Container,
  Header,
  Box,
  SpaceBetween,
  Alert,
  Spinner,
  Badge,
  Button,
  Grid,
  ButtonDropdown
} from '@cloudscape-design/components';
import PropTypes from 'prop-types';
import { 
  fetchProjectPDFs, 
  getPDFMetadata, 
  getPDFServingURL, 
  downloadPDFDirect,
  deletePDF,
  formatFileSize,
  formatLastModified
} from '../../services/pdfManagementService';

const PDFDisplaySection = ({
  projectId,
  projectName,
  autoLoad = true,
  phase = null,
  refreshTrigger = 0
}) => {
  const [pdfs, setPdfs] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [lastUpdated, setLastUpdated] = useState(null);
  const [metadata, setMetadata] = useState(null);

  // Load PDFs when component mounts or projectId changes
  useEffect(() => {
    if (autoLoad && projectId) {
      loadPDFs();
    }
  }, [projectId, autoLoad]);

  // Also refresh when external refresh trigger changes
  useEffect(() => {
    if (refreshTrigger > 0) {
      console.log(`🔄 PDFDisplaySection: External refresh trigger changed to ${refreshTrigger} for project ${projectId} - refreshing PDFs`);
      loadPDFs();
    }
  }, [refreshTrigger]);

  const loadPDFs = async () => {
    if (!projectId) {
      console.log('PDFDisplaySection: No project ID provided');
      return;
    }

    console.log('📄 PDFDisplaySection: Loading PDFs for project:', projectId);
    setLoading(true);
    setError(null);

    try {
      const [pdfResponse, metadataResponse] = await Promise.all([
        fetchProjectPDFs(projectId),
        getPDFMetadata(projectId)
      ]);
      
      console.log('📄 PDFDisplaySection: PDF response:', pdfResponse);
      console.log('📄 PDFDisplaySection: Metadata response:', metadataResponse);
      
      if (pdfResponse.success) {
        setPdfs(pdfResponse.pdfs || []);
        setMetadata(metadataResponse.success ? metadataResponse : null);
        setLastUpdated(new Date());
        console.log('📄 PDFDisplaySection: ✅ Loaded', pdfResponse.pdfs?.length || 0, 'PDFs');
      } else {
        setError(pdfResponse.message || 'Failed to load PDFs');
        setPdfs([]);
        console.log('📄 PDFDisplaySection: ❌ Failed to load PDFs:', pdfResponse.message);
      }
    } catch (err) {
      console.error('📄 PDFDisplaySection: 💥 Error loading PDFs:', err);
      setError('Failed to load PDFs');
      setPdfs([]);
    } finally {
      setLoading(false);
    }
  };

  const handleRefresh = () => {
    console.log('📄 PDFDisplaySection: Manual refresh triggered');
    loadPDFs();
  };

  const handleDownloadPDF = async (pdf) => {
    try {
      console.log('📄 PDFDisplaySection: Downloading PDF:', pdf.filename);
      const blob = await downloadPDFDirect(projectId, pdf.filename);
      
      // Create download link
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = pdf.filename;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
      
      console.log('📄 PDFDisplaySection: ✅ PDF downloaded successfully');
    } catch (error) {
      console.error('📄 PDFDisplaySection: ❌ Error downloading PDF:', error);
      setError(`Failed to download PDF: ${error.message}`);
    }
  };

  const handleViewPDF = (pdf) => {
    const url = getPDFServingURL(projectId, pdf.filename, false);
    window.open(url, '_blank');
  };

  const handleDeletePDF = async (pdf) => {
    if (!window.confirm(`Are you sure you want to delete ${pdf.filename}?`)) {
      return;
    }

    try {
      console.log('📄 PDFDisplaySection: Deleting PDF:', pdf.filename);
      const result = await deletePDF(projectId, pdf.filename);
      
      if (result.success) {
        console.log('📄 PDFDisplaySection: ✅ PDF deleted successfully');
        // Refresh the list
        loadPDFs();
      } else {
        setError(`Failed to delete PDF: ${result.message}`);
      }
    } catch (error) {
      console.error('📄 PDFDisplaySection: ❌ Error deleting PDF:', error);
      setError(`Failed to delete PDF: ${error.message}`);
    }
  };

  const getPDFActions = (pdf) => [
    {
      id: 'download',
      text: 'Download',
      iconName: 'download'
    },
    {
      id: 'delete',
      text: 'Delete',
      iconName: 'remove'
    }
  ];

  const handlePDFAction = (pdf, action) => {
    switch (action.id) {
      case 'download':
        handleDownloadPDF(pdf);
        break;
      case 'delete':
        handleDeletePDF(pdf);
        break;
      default:
        console.warn('Unknown PDF action:', action.id);
    }
  };

  // Filter PDFs by phase if specified
  const filteredPDFs = phase 
    ? pdfs.filter(pdf => pdf.phase === phase || pdf.filename.toLowerCase().includes(phase.toLowerCase()))
    : pdfs;

  // Don't render anything if no PDFs and not loading
  if (!loading && filteredPDFs.length === 0 && !error) {
    return null;
  }

  return (
    <Container
      header={
        <Header
          variant="h3"
          description={`PDF documents for ${projectName || projectId}`}
          actions={
            <SpaceBetween direction="horizontal" size="xs">
              <Button
                variant="normal"
                iconName="refresh"
                onClick={handleRefresh}
                loading={loading}
              >
                Refresh
              </Button>
            </SpaceBetween>
          }
        >
          Project PDFs
        </Header>
      }
    >
      <SpaceBetween size="l">
        {/* Loading State */}
        {loading && (
          <Box textAlign="center" padding="l">
            <Spinner size="large" />
            <Box variant="p" color="text-body-secondary" margin={{ top: 's' }}>
              Loading PDFs...
            </Box>
          </Box>
        )}

        {/* Error State */}
        {error && (
          <Alert
            type="error"
            dismissible
            onDismiss={() => setError(null)}
            header="Failed to load PDFs"
            action={
              <Button onClick={handleRefresh} variant="primary">
                Retry
              </Button>
            }
          >
            {error}
          </Alert>
        )}

        {/* Success State with PDFs */}
        {!loading && filteredPDFs.length > 0 && (
          <SpaceBetween size="l">
            {/* Summary */}
            <Box>
              <SpaceBetween direction="horizontal" size="s" alignItems="center">
                <Badge color="blue">
                  {filteredPDFs.length} PDF{filteredPDFs.length !== 1 ? 's' : ''}
                </Badge>
                {metadata && (
                  <Badge color="grey">
                    {formatFileSize(metadata.totalSize)}
                  </Badge>
                )}
                {lastUpdated && (
                  <Box variant="small" color="text-body-secondary">
                    Last updated: {lastUpdated.toLocaleTimeString()}
                  </Box>
                )}
              </SpaceBetween>
            </Box>

            {/* PDF Grid */}
            <Grid gridDefinition={filteredPDFs.length === 1 ? [{ colspan: 12 }] : [{ colspan: 6 }, { colspan: 6 }]}>
              {filteredPDFs.map((pdf, index) => (
                <Box key={index} padding="s" style={{ border: '1px solid #e9ecef', borderRadius: '8px' }}>
                  <SpaceBetween size="s">
                    {/* PDF Header */}
                    <Box>
                      <SpaceBetween direction="horizontal" size="s" alignItems="center">
                        <Box variant="h5">
                          {pdf.filename}
                        </Box>
                        <ButtonDropdown
                          items={getPDFActions(pdf)}
                          onItemClick={({ detail }) => handlePDFAction(pdf, detail)}
                          variant="icon"
                          ariaLabel="PDF actions"
                        />
                      </SpaceBetween>
                    </Box>

                    {/* PDF Metadata */}
                    <Box>
                      <SpaceBetween direction="horizontal" size="s" alignItems="center">
                        <Badge color="green">
                          {pdf.phase || 'Unknown Phase'}
                        </Badge>
                        <Badge color="grey">
                          {formatFileSize(pdf.size)}
                        </Badge>
                      </SpaceBetween>
                      
                      <Box variant="small" color="text-body-secondary" margin={{ top: 'xs' }}>
                        Generated: {formatLastModified(pdf.last_modified)}
                      </Box>
                    </Box>

                    {/* PDF Preview/Actions */}
                    <Box>
                      <SpaceBetween direction="horizontal" size="s">
                        <Button
                          variant="primary"
                          iconName="download"
                          onClick={() => handleDownloadPDF(pdf)}
                          size="small"
                        >
                          Download
                        </Button>
                      </SpaceBetween>
                    </Box>
                  </SpaceBetween>
                </Box>
              ))}
            </Grid>
          </SpaceBetween>
        )}

        {/* Empty State */}
        {!loading && filteredPDFs.length === 0 && !error && (
          <Box textAlign="center" padding="xl">
            <SpaceBetween size="m">
              <Box variant="h4" color="text-body-secondary">
                No PDFs found
              </Box>
              <Box variant="p" color="text-body-secondary">
                Generate PDFs by creating specifications in the chat and using the PDF Options button.
              </Box>
              <Button onClick={handleRefresh} variant="primary">
                Check for PDFs
              </Button>
            </SpaceBetween>
          </Box>
        )}
      </SpaceBetween>
    </Container>
  );
};

PDFDisplaySection.propTypes = {
  projectId: PropTypes.string.isRequired,
  projectName: PropTypes.string,
  autoLoad: PropTypes.bool,
  phase: PropTypes.string,
  refreshTrigger: PropTypes.number
};

export default PDFDisplaySection;