import { getApiConfig } from '../config/apiConfig';
import { makeApiCall } from './api';

/**
 * PDF Management Service
 * Handles fetching, listing, and managing PDFs similar to diagrams and code
 */

/**
 * Fetch existing PDFs for a project
 * @param {string} projectId - The project identifier
 * @returns {Promise<Object>} The PDFs response
 */
export const fetchProjectPDFs = async (projectId) => {
  console.log('📄 PDFService: fetchProjectPDFs called with projectId:', projectId);
  
  if (!projectId || typeof projectId !== 'string') {
    throw new Error('Project ID is required and must be a string');
  }

  try {
    const config = getApiConfig();
    const endpoint = `${config.endpoints.api}/pdfs/${projectId}/list`;
    
    console.log('📄 PDFService: Making API call to:', endpoint);
    
    const response = await makeApiCall(endpoint, {
      method: 'GET'
    }, true); // Require authentication

    console.log('📄 PDFService: API response:', response);

    return {
      success: response.success || false,
      pdfs: response.metadata?.pdfs || [],
      totalPDFs: response.metadata?.total_pdfs || 0,
      totalSize: response.metadata?.total_size || 0,
      projectId: response.project_id || projectId,
      message: response.message || 'PDFs retrieved'
    };
  } catch (error) {
    console.error('📄 PDFService: Error fetching PDFs:', error);
    return {
      success: false,
      pdfs: [],
      totalPDFs: 0,
      totalSize: 0,
      projectId: projectId,
      message: 'Failed to fetch PDFs',
      error: error.message
    };
  }
};

