/**
 * Get PDF serving URL
 * @param {string} projectId - The project identifier
 * @param {string} filename - The PDF filename
 * @param {boolean} download - Whether to download or view inline
 * @returns {string} The PDF serving URL
 */
export const getPDFServingURL = (projectId, filename, download = false) => {
  const config = getApiConfig();
  const action = download ? 'download' : 'serve';
  return `${config.baseUrl}/api/pdfs/${projectId}/${action}/${filename}`;
};

/**
 * Download PDF directly
 * @param {string} projectId - The project identifier
 * @param {string} filename - The PDF filename
 * @returns {Promise<Blob>} The PDF blob
 */
export const downloadPDFDirect = async (projectId, filename) => {
  console.log('📄 PDFService: downloadPDFDirect called', { projectId, filename });
  
  try {
    const authService = (await import('./authService')).default;
    const authHeader = await authService.getAuthHeader();
    const config = getApiConfig();
    
    const url = getPDFServingURL(projectId, filename, false);
    
    const response = await fetch(url, {
      method: 'GET',
      headers: {
        'Accept': 'application/pdf',
        ...(authHeader && { 'Authorization': authHeader })
      },
      credentials: 'include'
    });
    
    if (!response.ok) {
      const errorText = await response.text().catch(() => 'Unknown error');
      throw new Error(`Failed to download PDF: ${response.status} - ${errorText}`);
    }
    
    return await response.blob();
  } catch (error) {
    console.error('📄 PDFService: Error downloading PDF:', error);
    throw error;
  }
};

