/**
 * Check if PDF exists for a phase
 * @param {string} projectId - The project identifier
 * @param {string} phase - The SDLC phase
 * @returns {Promise<Object>} The existence check result
 */
export const checkPDFExists = async (projectId, phase) => {
  try {
    const metadata = await getPDFMetadata(projectId);
    
    if (!metadata.success) {
      return { exists: false, pdf: null };
    }
    
    // Look for PDF matching the phase
    const phasePDF = metadata.pdfs.find(pdf => 
      pdf.phase === phase || pdf.filename.toLowerCase().includes(phase.toLowerCase())
    );
    
    return {
      exists: !!phasePDF,
      pdf: phasePDF || null,
      totalPDFs: metadata.totalPDFs
    };
  } catch (error) {
    console.error('📄 PDFService: Error checking PDF existence:', error);
    return { exists: false, pdf: null, error: error.message };
  }
};

/**
 * Get the most recent PDF for a phase
 * @param {string} projectId - The project identifier
 * @param {string} phase - The SDLC phase
 * @returns {Promise<Object>} The most recent PDF
 */
export const getRecentPDF = async (projectId, phase) => {
  try {
    const metadata = await getPDFMetadata(projectId);
    
    if (!metadata.success || !metadata.pdfs.length) {
      return { found: false, pdf: null };
    }
    
    // Filter PDFs for the specific phase
    const phasePDFs = metadata.pdfs.filter(pdf => 
      pdf.phase === phase || pdf.filename.toLowerCase().includes(phase.toLowerCase())
    );
    
    if (!phasePDFs.length) {
      return { found: false, pdf: null };
    }
    
    // Sort by last_modified date (most recent first)
    const sortedPDFs = phasePDFs.sort((a, b) => 
      new Date(b.last_modified) - new Date(a.last_modified)
    );
    
    return {
      found: true,
      pdf: sortedPDFs[0],
      totalForPhase: phasePDFs.length
    };
  } catch (error) {
    console.error('📄 PDFService: Error getting recent PDF:', error);
    return { found: false, pdf: null, error: error.message };
  }
};

/**
 * Format PDF file size for display
 * @param {number} bytes - File size in bytes
 * @returns {string} Formatted file size
 */
export const formatFileSize = (bytes) => {
  if (!bytes || bytes === 0) return '0 B';
  
  const k = 1024;
  const sizes = ['B', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  
  return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
};

/**
 * Format PDF last modified date for display
 * @param {string} dateString - ISO date string
 * @returns {string} Formatted date
 */
export const formatLastModified = (dateString) => {
  if (!dateString) return 'Unknown';
  
  try {
    const date = new Date(dateString);
    return date.toLocaleString();
  } catch (error) {
    return 'Invalid date';
  }
};