import React, { useState, useEffect } from 'react';
import {
  Container,
  Header,
  SpaceBetween,
  Button,
  Box,
  StatusIndicator,
  Alert,
  Cards,
  Badge,
  Spinner
} from '@cloudscape-design/components';

const JiraIntegration = () => {
  const [authStatus, setAuthStatus] = useState({
    status: 'not_authenticated',
    is_authenticated: false,
    process_running: false,
    credentials_exist: false
  });
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');

  // Check auth status on component mount
  useEffect(() => {
    checkAuthStatus();
  }, []);

  const checkAuthStatus = async () => {
    try {
      const response = await fetch('/api/atlassian/auth/status');
      const data = await response.json();
      
      if (data.success) {
        setAuthStatus(data.data);
      } else {
        setError('Failed to check authentication status');
      }
    } catch (err) {
      setError('Error checking authentication status');
      console.error('Auth status check error:', err);
    }
  };

  const startAuthentication = async () => {
    setLoading(true);
    setError('');
    setMessage('');

    try {
      const response = await fetch('/api/atlassian/auth/start', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      const data = await response.json();

      if (data.success) {
        setMessage(data.message);
        setAuthStatus(prev => ({ ...prev, process_running: true, status: 'authenticating' }));
        
        // Open the authentication URL in a new tab
        if (data.data.auth_url) {
          window.open(data.data.auth_url, '_blank');
        }
        
        // Start polling for completion
        pollForCompletion();
      } else {
        setError(data.message || 'Failed to start authentication');
      }
    } catch (err) {
      setError('Error starting authentication process');
      console.error('Auth start error:', err);
    } finally {
      setLoading(false);
    }
  };

  const pollForCompletion = () => {
    const pollInterval = setInterval(async () => {
      try {
        const response = await fetch('/api/atlassian/auth/check', {
          method: 'POST',
        });
        const data = await response.json();

        if (data.success) {
          setAuthStatus(data.data);
          
          if (data.authenticated) {
            setMessage('Authentication completed successfully!');
            clearInterval(pollInterval);
          }
        }
      } catch (err) {
        console.error('Polling error:', err);
      }
    }, 3000); // Poll every 3 seconds

    // Stop polling after 5 minutes
    setTimeout(() => {
      clearInterval(pollInterval);
    }, 300000);
  };

  const stopAuthentication = async () => {
    try {
      const response = await fetch('/api/atlassian/auth/stop', {
        method: 'POST',
      });
      const data = await response.json();

      if (data.success) {
        setMessage('Authentication process stopped');
        setAuthStatus(prev => ({ ...prev, process_running: false, status: 'not_authenticated' }));
      }
    } catch (err) {
      setError('Error stopping authentication process');
      console.error('Auth stop error:', err);
    }
  };

  const clearCredentials = async () => {
    try {
      const response = await fetch('/api/atlassian/auth/credentials', {
        method: 'DELETE',
      });
      const data = await response.json();

      if (data.success) {
        setMessage('Credentials cleared successfully');
        setAuthStatus({
          status: 'not_authenticated',
          is_authenticated: false,
          process_running: false,
          credentials_exist: false
        });
      }
    } catch (err) {
      setError('Error clearing credentials');
      console.error('Clear credentials error:', err);
    }
  };

  const testConnection = async () => {
    setLoading(true);
    try {
      const response = await fetch('/api/atlassian/test');
      const data = await response.json();

      if (data.success) {
        setMessage('Atlassian connection test successful!');
      } else {
        setError(data.detail || 'Connection test failed');
      }
    } catch (err) {
      setError('Error testing connection');
      console.error('Connection test error:', err);
    } finally {
      setLoading(false);
    }
  };

  const getStatusIndicator = () => {
    switch (authStatus.status) {
      case 'authenticated':
        return <StatusIndicator type="success">Connected to Atlassian</StatusIndicator>;
      case 'authenticating':
        return <StatusIndicator type="in-progress">Authentication in progress...</StatusIndicator>;
      case 'expired':
        return <StatusIndicator type="warning">Authentication expired</StatusIndicator>;
      default:
        return <StatusIndicator type="error">Not connected</StatusIndicator>;
    }
  };

  return (
    <Container>
      <SpaceBetween direction="vertical" size="l">
        <Header
          variant="h1"
          description="Connect your Atlassian account to access Jira issues and Confluence content."
        >
          Jira Integration
        </Header>

        {/* Status Section */}
        <Box>
          <SpaceBetween direction="vertical" size="m">
            <Header variant="h2">Connection Status</Header>
            <Box>
              {getStatusIndicator()}
              <Box margin={{ top: 's' }}>
                <SpaceBetween direction="horizontal" size="l">
                  <Box>
                    <Badge color={authStatus.process_running ? 'green' : 'grey'}>
                      Process: {authStatus.process_running ? 'Running' : 'Stopped'}
                    </Badge>
                  </Box>
                  <Box>
                    <Badge color={authStatus.credentials_exist ? 'green' : 'grey'}>
                      Credentials: {authStatus.credentials_exist ? 'Stored' : 'None'}
                    </Badge>
                  </Box>
                </SpaceBetween>
              </Box>
            </Box>
          </SpaceBetween>
        </Box>

        {/* Messages */}
        {message && (
          <Alert type="success" dismissible onDismiss={() => setMessage('')}>
            {message}
          </Alert>
        )}

        {error && (
          <Alert type="error" dismissible onDismiss={() => setError('')}>
            {error}
          </Alert>
        )}

        {/* Actions Section */}
        <Box>
          <SpaceBetween direction="vertical" size="m">
            <Header variant="h2">Actions</Header>
            
            <SpaceBetween direction="vertical" size="s">
              {!authStatus.is_authenticated && !authStatus.process_running && (
                <Box>
                  <SpaceBetween direction="vertical" size="xs">
                    <Button 
                      variant="primary"
                      onClick={startAuthentication} 
                      disabled={loading}
                      iconName="external"
                    >
                      {loading ? 'Starting...' : 'Connect to Atlassian'}
                    </Button>
                    <Box fontSize="body-s" color="text-body-secondary">
                      This will open a new tab for Atlassian OAuth authentication.
                    </Box>
                  </SpaceBetween>
                </Box>
              )}

              {authStatus.process_running && (
                <Box>
                  <SpaceBetween direction="vertical" size="xs">
                    <Button 
                      onClick={stopAuthentication}
                      iconName="close"
                    >
                      Stop Authentication
                    </Button>
                    <Box fontSize="body-s" color="text-body-secondary">
                      Complete the OAuth flow in the opened browser tab, then wait for automatic detection.
                    </Box>
                  </SpaceBetween>
                </Box>
              )}

              {authStatus.is_authenticated && (
                <SpaceBetween direction="horizontal" size="s">
                  <Button 
                    onClick={testConnection}
                    disabled={loading}
                    iconName="status-positive"
                  >
                    {loading ? (
                      <>
                        <Spinner size="normal" /> Testing...
                      </>
                    ) : (
                      'Test Connection'
                    )}
                  </Button>
                  <Button 
                    onClick={clearCredentials}
                    iconName="remove"
                  >
                    Disconnect
                  </Button>
                </SpaceBetween>
              )}

              <Button 
                onClick={checkAuthStatus}
                variant="link"
                iconName="refresh"
              >
                Refresh Status
              </Button>
            </SpaceBetween>
          </SpaceBetween>
        </Box>

        {/* Instructions Section */}
        <Box>
          <SpaceBetween direction="vertical" size="m">
            <Header variant="h2">How it works</Header>
            <Box>
              <ol>
                <li>1. Click "Connect to Atlassian" to start the authentication process</li>
                <li>2. Complete the OAuth flow in the opened browser tab</li>
                <li>3. Return to this page - the system will automatically detect successful authentication</li>
                <li>4. Once connected, you can use Jira and Confluence features throughout the application</li>
              </ol>
            </Box>
          </SpaceBetween>
        </Box>
      </SpaceBetween>
    </Container>
  );
};

export default JiraIntegration;