/**
 * Epics Panel Component
 * 
 * Displays epics and their features in a beautiful CloudScape panel for the requirements phase
 */

import { useState, useEffect } from 'react';
import {
  Container,
  Header,
  SpaceBetween,
  Box,
  Badge,
  Alert,
  Spinner,
  TextContent,
  Button,
  Icon,
  ExpandableSection,
  Cards,
  Pagination,
  StatusIndicator,
  ProgressBar
} from '@cloudscape-design/components';
import { getEpics, getJiraMetadata } from '../../services/jiraService';
import './EpicsPanel.css';

const EpicsPanel = ({ projectId, refreshTrigger = 0 }) => {
  const [epics, setEpics] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [metadata, setMetadata] = useState({ total_epics: 0 });
  const [isGenerating, setIsGenerating] = useState(false);
  const [currentPageIndex, setCurrentPageIndex] = useState(1);
  const [pageSize, setPageSize] = useState(4);

  // Fetch epics data
  const fetchEpics = async () => {
    if (!projectId) return;

    try {
      setLoading(true);
      setError(null);

      const [epicsData, metadataData] = await Promise.all([
        getEpics(projectId),
        getJiraMetadata(projectId)
      ]);

      setEpics(epicsData);
      setMetadata(metadataData);
    } catch (err) {
      console.error('Error fetching epics:', err);
      setError('Failed to load epics');
    } finally {
      setLoading(false);
    }
  };

  // Fetch data on component mount and when refresh trigger changes
  useEffect(() => {
    fetchEpics();
  }, [projectId, refreshTrigger]);

  // Show generating state when refresh trigger changes (indicates new epics being generated)
  useEffect(() => {
    if (refreshTrigger > 0) {
      setIsGenerating(true);
      // Clear generating state after a delay
      const timer = setTimeout(() => {
        setIsGenerating(false);
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [refreshTrigger]);

  // Paginate epics
  const paginatedEpics = epics.slice(
    (currentPageIndex - 1) * pageSize,
    currentPageIndex * pageSize
  );

  // Loading state
  if (loading) {
    return (
      <Container
        className="epics-container loading"
        header={
          <Header
            variant="h3"
            description={isGenerating ? "Generating new epics..." : "Fetching project epics..."}
            className="epics-header"
          >
            <SpaceBetween direction="horizontal" size="xs" alignItems="center">
              <Icon name="status-in-progress" />
              <span>Project Epics</span>
            </SpaceBetween>
          </Header>
        }
      >
        <Box textAlign="center" padding="xl" className="epics-loading-state">
          <SpaceBetween size="l" alignItems="center">
            <div className="epics-loading-animation">
              <Spinner size="large" />
            </div>
            <TextContent>
              <h3>{isGenerating ? "📋 Generating epics..." : "Loading epics..."}</h3>
              <p>{isGenerating ? "Creating project structure and epic definitions from requirements" : "Gathering project structure and epic definitions"}</p>
            </TextContent>
            <ProgressBar value={isGenerating ? 80 : 60} variant={isGenerating ? "flash" : "normal"} />
          </SpaceBetween>
        </Box>
      </Container>
    );
  }

  // Error state
  if (error) {
    return (
      <Container
        className="epics-container error"
        header={
          <Header
            variant="h3"
            description="Unable to load epics"
            className="epics-header error"
          >
            <SpaceBetween direction="horizontal" size="xs" alignItems="center">
              <Icon name="status-negative" variant="error" />
              <span>Project Epics</span>
            </SpaceBetween>
          </Header>
        }
      >
        <Alert
          type="error"
          header="Connection Failed"
          className="epics-error-alert"
        >
          <SpaceBetween size="m">
            <div className="error-message">{error}</div>
            <div className="error-actions">
              <Button
                onClick={fetchEpics}
                iconName="refresh"
                variant="primary"
              >
                Retry Connection
              </Button>
            </div>
          </SpaceBetween>
        </Alert>
      </Container>
    );
  }

  // Empty state
  if (!epics || epics.length === 0) {
    return (
      <Container
        className="epics-container empty"
        header={
          <Header
            variant="h3"
            description="Ready to create epics"
            actions={
              <Button
                onClick={fetchEpics}
                iconName="refresh"
                variant="icon"
                ariaLabel="Refresh epics"
              />
            }
            className="epics-header"
          >
            <SpaceBetween direction="horizontal" size="xs" alignItems="center">
              <Icon name="folder" />
              <span>Project Epics</span>
            </SpaceBetween>
          </Header>
        }
      >
        <Box textAlign="center" padding="xl" className="epics-empty-state">
          <SpaceBetween size="l" alignItems="center">
            <div className="empty-state-icon">
              <Icon name="folder" size="large" variant="subtle" />
            </div>
            <TextContent>
              <h3>No epics defined yet</h3>
              <p className="empty-description">
                Epics will appear here automatically when generated through the chat interface.
              </p>
              <div className="empty-suggestions">
                <Badge color="blue">💡 Try asking: "Break down this project into epics and features"</Badge>
              </div>
            </TextContent>
            <Button
              onClick={fetchEpics}
              iconName="refresh"
              variant="normal"
            >
              Check for epics
            </Button>
          </SpaceBetween>
        </Box>
      </Container>
    );
  }

  // Main render with Cards component
  return (
    <Container
      className="epics-container"
      header={
        <Header
          variant="h3"
          description={
            <SpaceBetween direction="horizontal" size="s" alignItems="center">
              <span>{metadata.total_epics} epic{metadata.total_epics !== 1 ? 's' : ''} defined</span>
              {isGenerating ? (
                <StatusIndicator type="in-progress">Generating...</StatusIndicator>
              ) : (
                <StatusIndicator type="success">Active</StatusIndicator>
              )}
            </SpaceBetween>
          }
          actions={
            <Button
              onClick={fetchEpics}
              iconName="refresh"
              variant="icon"
              ariaLabel="Refresh epics"
              loading={loading || isGenerating}
            />
          }
          className="epics-header"
        >
          <SpaceBetween direction="horizontal" size="xs" alignItems="center">
            <Icon name="folder" />
            <span>Project Epics</span>
            {isGenerating && <Spinner size="small" />}
          </SpaceBetween>
        </Header>
      }
    >
      <SpaceBetween size="l">
        <div className="epics-grid">
          <Cards
            cardDefinition={{
              header: (epic, index) => (
                <div className="epic-card-header">
                  <SpaceBetween direction="horizontal" size="s" alignItems="center">
                    <div className="epic-icon">📋</div>
                    <TextContent>
                      <h4 className="epic-title">
                        {epic.title || `Epic ${index + 1}`}
                      </h4>
                    </TextContent>
                    <StatusIndicator type="success">
                    </StatusIndicator>
                  </SpaceBetween>
                </div>
              ),
              sections: [
                {
                  id: "description",
                  content: (epic) => epic.description && (
                    <div className="epic-description">
                      <TextContent>
                        <p className="description-text">
                          {epic.description}
                        </p>
                      </TextContent>
                    </div>
                  )
                },
                {
                  id: "features",
                  content: (epic) => epic.features && epic.features.length > 0 && (
                    <div className="epic-features">
                      <ExpandableSection
                        headerText={
                          <SpaceBetween direction="horizontal" size="xs" alignItems="center">
                            <Icon name="list" size="small" />
                            <span>Features ({epic.features.length})</span>
                          </SpaceBetween>
                        }
                        variant="footer"
                        defaultExpanded={epic.features.length <= 3}
                        className="features-section"
                      >
                        <Box>
                          <ul style={{
                            listStyleType: 'disc',
                            paddingLeft: '20px',
                            margin: '8px 0',
                            lineHeight: '1.5'
                          }}>
                            {epic.features.map((feature, featureIndex) => (
                              <li key={featureIndex} style={{
                                marginBottom: '6px',
                                color: '#16191f'
                              }}>
                                {feature}
                              </li>
                            ))}
                          </ul>
                        </Box>
                      </ExpandableSection>
                    </div>
                  )
                },
                {
                  id: "metadata",
                  content: (epic) => (
                    <div className="epic-metadata">
                      <SpaceBetween direction="horizontal" size="s" alignItems="center">
                        <Badge
                          color="blue"
                          className="epic-badge"
                        >
                          Epic
                        </Badge>
                        {epic.created_at && (
                          <div className="epic-date">
                            <Icon name="calendar" size="small" />
                            <span>Created {new Date(epic.created_at).toLocaleDateString()}</span>
                          </div>
                        )}
                      </SpaceBetween>
                    </div>
                  )
                }
              ]
            }}
            items={paginatedEpics}
            loadingText="Loading epics..."
            empty={
              <Box textAlign="center" padding="xl" className="epics-empty">
                <SpaceBetween size="l" alignItems="center">
                  <Icon name="folder" size="large" variant="subtle" />
                  <TextContent>
                    <h3>No epics to display</h3>
                    <p>Epics will appear here when created.</p>
                  </TextContent>
                </SpaceBetween>
              </Box>
            }
            cardsPerRow={[
              { cards: 1 },
              { minWidth: 700, cards: 2 }
            ]}
            className="epics-cards"
          />
        </div>

        {epics.length > pageSize && (
          <Pagination
            currentPageIndex={currentPageIndex}
            pagesCount={Math.ceil(epics.length / pageSize)}
            onChange={({ detail }) => setCurrentPageIndex(detail.currentPageIndex)}
          />
        )}
      </SpaceBetween>
    </Container>
  );
};

export default EpicsPanel;