import React, { useState } from 'react';
import {
  Button,
  SpaceBetween,
  Alert
} from '@cloudscape-design/components';
import { generateSingleSpecificationPDF, downloadPDFBlob, generatePDFFilename } from '../../services/pdfService';

/**
 * Simple PDF download button for specifications
 */
const PDFDownloadButton = ({ 
  conversationId, 
  phase = 'requirements', 
  projectName = null,
  variant = 'primary',
  size = 'normal',
  disabled = false
}) => {
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState(null);

  const handleDownloadPDF = async () => {
    if (!conversationId) {
      setError('No conversation ID available for PDF generation');
      return;
    }

    setIsGenerating(true);
    setError(null);

    try {
      console.log('📄 Generating PDF for:', { conversationId, phase, projectName });
      
      // Generate PDF
      const pdfBlob = await generateSingleSpecificationPDF(conversationId, phase);
      console.log('✅ PDF generated successfully, blob size:', pdfBlob.size);
      
      // Generate filename
      const filename = generatePDFFilename(phase, 'single', projectName);
      console.log('📁 Generated filename:', filename);

      // Download the PDF
      downloadPDFBlob(pdfBlob, filename);
      console.log('⬇️ PDF download initiated');
      
    } catch (error) {
      console.error('❌ PDF generation error:', error);
      setError(error.message || 'Failed to generate PDF');
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <SpaceBetween size="s">
      <Button
        variant={variant}
        size={size}
        disabled={disabled || isGenerating || !conversationId}
        loading={isGenerating}
        onClick={handleDownloadPDF}
        iconName="download"
      >
        {isGenerating ? 'Generating PDF...' : 'Download PDF'}
      </Button>
      
      {error && (
        <Alert type="error" dismissible onDismiss={() => setError(null)}>
          {error}
        </Alert>
      )}
    </SpaceBetween>
  );
};

export default PDFDownloadButton;