/**
 * Jira OAuth Service for React Frontend
 * 
 * This service handles the OAuth flow for Jira integration, including:
 * - Generating OAuth URLs
 * - Handling OAuth callbacks
 * - Managing OAuth state
 * - Integration with backend API
 */

import { makeApiCall } from './api';

class JiraOAuthService {
  constructor() {
    this.authListeners = [];
    this.authState = {
      isAuthenticated: false,
      tokenInfo: null,
      userInfo: null
    };
  }

  /**
   * Generate OAuth authorization URL
   * @param {string} state - Optional state parameter for CSRF protection
   * @returns {Promise<Object>} - Auth URL and state information
   */
  async generateAuthUrl(state = null) {
    try {
      const response = await makeApiCall('/api/oauth/jira/auth-url', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ state })
      });

      // Store state in session storage for validation
      if (response.state) {
        sessionStorage.setItem('oauth_state', response.state);
      }

      return response;
    } catch (error) {
      console.error('Error generating OAuth URL:', error);
      throw new Error(`Failed to generate OAuth URL: ${error.message}`);
    }
  }

  /**
   * Handle OAuth callback
   * @param {string} code - Authorization code from OAuth callback
   * @param {string} state - State parameter from OAuth callback
   * @returns {Promise<Object>} - Callback result
   */
  async handleOAuthCallback(code, state) {
    try {
      // Validate state
      const storedState = sessionStorage.getItem('oauth_state');
      if (state !== storedState) {
        throw new Error('Invalid state parameter - possible CSRF attack');
      }

      const response = await makeApiCall('/api/oauth/jira/callback', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ code, state })
      });

      if (response.success) {
        // Update auth state
        this.authState = {
          isAuthenticated: true,
          tokenInfo: {
            expires_in: response.expires_in,
            user_info: response.user_info
          },
          userInfo: response.user_info
        };

        // Clean up session storage
        sessionStorage.removeItem('oauth_state');

        // Notify listeners
        this.notifyAuthListeners(this.authState);
      }

      return response;
    } catch (error) {
      console.error('Error handling OAuth callback:', error);
      throw new Error(`OAuth callback failed: ${error.message}`);
    }
  }

  /**
   * Get current Jira authentication status
   * @returns {Promise<Object>} - Authentication status
   */
  async getAuthStatus() {
    try {
      const response = await makeApiCall('/api/oauth/jira/status', {
        method: 'GET'
      });

      console.log('Jira OAuth status response:', response);

      // Update local auth state
      this.authState = {
        isAuthenticated: response.authenticated,
        tokenInfo: response.authenticated ? {
          expires_at: response.expires_at,
          user_info: response.user_info
        } : null,
        userInfo: response.user_info
      };

      console.log('Updated Jira auth state:', this.authState);

      // Notify listeners
      this.notifyAuthListeners(this.authState);

      return response;
    } catch (error) {
      console.error('Error getting auth status:', error);
      // On error, assume not authenticated
      this.authState = {
        isAuthenticated: false,
        tokenInfo: null,
        userInfo: null
      };
      this.notifyAuthListeners(this.authState);
      throw error;
    }
  }

  /**
   * Get detailed token information
   * @returns {Promise<Object>} - Token information
   */
  async getTokenInfo() {
    try {
      const response = await makeApiCall('/api/oauth/jira/token', {
        method: 'GET'
      });

      return response;
    } catch (error) {
      console.error('Error getting token info:', error);
      throw new Error(`Failed to get token info: ${error.message}`);
    }
  }

  /**
   * Register Jira token with MCP server
   * @returns {Promise<Object>} - Registration result
   */
  async registerWithMCP() {
    try {
      const response = await makeApiCall('/api/oauth/jira/register-with-mcp', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({})
      });

      return response;
    } catch (error) {
      console.error('Error registering with MCP:', error);
      throw new Error(`Failed to register with MCP: ${error.message}`);
    }
  }

  /**
   * Test Jira connection
   * @returns {Promise<Object>} - Connection test result
   */
  async testConnection() {
    try {
      const response = await makeApiCall('/api/oauth/jira/test-connection', {
        method: 'POST'
      });

      return response;
    } catch (error) {
      console.error('Error testing connection:', error);
      throw new Error(`Connection test failed: ${error.message}`);
    }
  }

  /**
   * Revoke Jira authentication
   * @returns {Promise<Object>} - Revocation result
   */
  async revokeAuthentication() {
    try {
      const response = await makeApiCall('/api/oauth/jira/revoke', {
        method: 'DELETE'
      });

      // Update auth state
      this.authState = {
        isAuthenticated: false,
        tokenInfo: null,
        userInfo: null
      };

      // Notify listeners
      this.notifyAuthListeners(this.authState);

      return response;
    } catch (error) {
      console.error('Error revoking authentication:', error);
      throw new Error(`Failed to revoke authentication: ${error.message}`);
    }
  }

  /**
   * Open OAuth popup and handle the flow
   * @returns {Promise<Object>} - OAuth flow result
   */
  async authenticateWithPopup() {
    try {
      console.log('Starting OAuth popup authentication...');
      
      // Step 1: Generate OAuth URL
      const authUrlResponse = await this.generateAuthUrl();
      console.log('Generated OAuth URL response:', authUrlResponse);
      
      if (!authUrlResponse.auth_url) {
        throw new Error('Failed to generate OAuth URL');
      }

      console.log('Opening OAuth popup with URL:', authUrlResponse.auth_url);

      // Step 2: Open OAuth popup
      const popup = window.open(
        authUrlResponse.auth_url,
        'jira-oauth',
        'width=600,height=700,scrollbars=yes,resizable=yes'
      );

      if (!popup) {
        throw new Error('Failed to open OAuth popup. Please allow popups for this site.');
      }

      console.log('Popup opened, waiting for auth code...');

      // Step 3: Wait for OAuth callback
      const authResult = await this.waitForAuthCode(popup, authUrlResponse.state);
      console.log('Auth result received:', authResult);

      if (authResult.success) {
        // Step 4: Handle callback
        console.log('Handling OAuth callback...');
        const callbackResponse = await this.handleOAuthCallback(
          authResult.code,
          authResult.state
        );
        console.log('Callback response:', callbackResponse);

        return callbackResponse;
      } else {
        throw new Error(authResult.error || 'Authentication failed');
      }
    } catch (error) {
      console.error('OAuth popup authentication error:', error);
      throw error;
    }
  }

  /**
   * Wait for authorization code from popup
   * @param {Window} popup - Popup window reference
   * @param {string} expectedState - Expected state parameter
   * @returns {Promise<Object>} - Authorization result
   */
  waitForAuthCode(popup, expectedState) {
    return new Promise((resolve, reject) => {
      const checkClosed = setInterval(() => {
        if (popup.closed) {
          clearInterval(checkClosed);
          reject(new Error('Authentication popup was closed'));
        }
      }, 1000);

      // Listen for messages from the popup
      const messageHandler = (event) => {
        console.log('Received message from popup:', event.data, 'from origin:', event.origin);
        
        // Only process messages from our own origin (the callback page)
        if (event.origin !== window.location.origin) {
          console.log('Ignoring message from external origin:', event.origin);
          return;
        }

        // Only process Jira OAuth messages
        if (!event.data || !event.data.type || !event.data.type.startsWith('JIRA_AUTH_')) {
          console.log('Ignoring non-Jira OAuth message:', event.data);
          return;
        }

        console.log('Processing Jira OAuth message:', event.data);

        if (event.data.type === 'JIRA_AUTH_SUCCESS') {
          console.log('Received JIRA_AUTH_SUCCESS');
          clearInterval(checkClosed);
          window.removeEventListener('message', messageHandler);
          popup.close();
          
          // Validate state
          if (event.data.state !== expectedState) {
            console.error('State mismatch:', event.data.state, 'vs', expectedState);
            reject(new Error('Invalid state parameter'));
            return;
          }
          
          console.log('State validated, resolving with success');
          resolve({
            success: true,
            code: event.data.code,
            state: event.data.state
          });
        } else if (event.data.type === 'JIRA_AUTH_ERROR') {
          console.log('Received JIRA_AUTH_ERROR:', event.data.error);
          clearInterval(checkClosed);
          window.removeEventListener('message', messageHandler);
          popup.close();
          reject(new Error(event.data.error));
        }
      };

      window.addEventListener('message', messageHandler);

      // Timeout after 5 minutes
      setTimeout(() => {
        clearInterval(checkClosed);
        window.removeEventListener('message', messageHandler);
        if (!popup.closed) {
          popup.close();
        }
        reject(new Error('Authentication timeout'));
      }, 300000);
    });
  }

  /**
   * Check if user is authenticated with Jira
   * @returns {boolean} - Authentication status
   */
  isAuthenticated() {
    return this.authState.isAuthenticated;
  }

  /**
   * Get current auth state
   * @returns {Object} - Current auth state
   */
  getAuthState() {
    return { ...this.authState };
  }

  /**
   * Add authentication state listener
   * @param {Function} callback - Callback function
   * @returns {Function} - Unsubscribe function
   */
  addAuthListener(callback) {
    this.authListeners.push(callback);
    return () => {
      this.authListeners = this.authListeners.filter(listener => listener !== callback);
    };
  }

  /**
   * Notify all auth listeners
   * @param {Object} authState - Current auth state
   */
  notifyAuthListeners(authState) {
    this.authListeners.forEach(callback => {
      try {
        callback(authState);
      } catch (error) {
        console.error('Auth listener error:', error);
      }
    });
  }

  /**
   * Initialize the service (check current auth status)
   * @returns {Promise<void>}
   */
  async initialize() {
    try {
      await this.getAuthStatus();
    } catch (error) {
      console.warn('Failed to initialize Jira OAuth service:', error);
      // Continue with unauthenticated state
    }
  }

  /**
   * Cleanup resources
   */
  cleanup() {
    this.authListeners = [];
    sessionStorage.removeItem('oauth_state');
  }
}

// Create singleton instance
const jiraOAuthService = new JiraOAuthService();

export default jiraOAuthService;