import { getApiConfig } from '../config/apiConfig';
import { makeApiCall } from './api';
import authService from './authService';

/**
 * PDF Service for handling PDF generation and download operations
 */

/**
 * Generate PDF for a single specification
 * @param {string} conversationId - Conversation ID
 * @param {string} phase - SDLC phase
 * @param {Object} options - PDF generation options
 * @returns {Promise<Blob>} PDF blob data
 */
export const generateSingleSpecificationPDF = async (conversationId, phase, options = {}) => {
  try {
    const requestBody = {
      conversation_ids: [conversationId],
      phases: [phase],
      document_type: 'single',
      include_branding: options.includeBranding !== false,
      include_headers: options.includeHeaders !== false,
      include_footers: options.includeFooters !== false,
      page_size: options.pageSize || 'letter'
    };

    // Use the centralized API service which handles authentication
    const result = await makeApiCall('/api/sdlc/generate-pdf', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(requestBody),
      credentials: 'include'
    }, true); // requireAuth = true
    
    if (!result.success) {
      throw new Error(result.message || 'PDF generation failed');
    }
    
    // Fetch the actual PDF from the S3 serving URL with authentication
    const apiConfig = getApiConfig();
    const authHeader = await authService.getAuthHeader();
    
    const pdfResponse = await fetch(`${apiConfig.baseUrl}${result.view_url}`, {
      method: 'GET',
      headers: {
        'Accept': 'application/pdf',
        ...(authHeader && { 'Authorization': authHeader })
      },
      credentials: 'include'
    });
    
    if (!pdfResponse.ok) {
      const errorText = await pdfResponse.text().catch(() => 'Unknown error');
      throw new Error(`Failed to fetch generated PDF: ${pdfResponse.status} - ${errorText}`);
    }
    
    return await pdfResponse.blob();
  } catch (error) {
    console.error('Error generating single specification PDF:', error);
    throw new Error(`Failed to generate PDF: ${error.message}`);
  }
};

