/**
 * Download PDF for a specific specification
 * @param {string} conversationId - Conversation ID
 * @param {string} phase - SDLC phase
 * @returns {Promise<Blob>} PDF blob data
 */
export const downloadSpecificationPDF = async (conversationId, phase) => {
  try {
    // Use the centralized API service which handles authentication
    const response = await makeApiCall(`/api/sdlc/download-pdf/${conversationId}/${phase}`, {
      method: 'GET'
    }, true); // requireAuth = true

    // If the response is already a blob, return it
    if (response instanceof Blob) {
      return response;
    }
    
    // If it's JSON with a URL, fetch the actual PDF
    if (response.view_url) {
      const apiConfig = getApiConfig();
      const authHeader = await authService.getAuthHeader();
      
      const pdfResponse = await fetch(`${apiConfig.baseUrl}${response.view_url}`, {
        method: 'GET',
        headers: {
          'Accept': 'application/pdf',
          ...(authHeader && { 'Authorization': authHeader })
        },
        credentials: 'include'
      });
      
      if (!pdfResponse.ok) {
        throw new Error(`Failed to fetch PDF: ${pdfResponse.status}`);
      }
      
      return await pdfResponse.blob();
    }
    
    throw new Error('Invalid response format');
  } catch (error) {
    console.error('Error downloading specification PDF:', error);
    throw new Error(`Failed to download PDF: ${error.message}`);
  }
};

/**
 * Create a blob URL for PDF viewing
 * @param {Blob} pdfBlob - PDF blob data
 * @returns {string} Blob URL
 */
export const createPDFBlobURL = (pdfBlob) => {
  return URL.createObjectURL(pdfBlob);
};

/**
 * Revoke a blob URL to free memory
 * @param {string} blobUrl - Blob URL to revoke
 */
export const revokePDFBlobURL = (blobUrl) => {
  URL.revokeObjectURL(blobUrl);
};

/**
 * Download PDF blob as file
 * @param {Blob} pdfBlob - PDF blob data
 * @param {string} filename - Filename for download
 */
export const downloadPDFBlob = (pdfBlob, filename) => {
  const url = createPDFBlobURL(pdfBlob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  revokePDFBlobURL(url);
};

/**
 * Generate filename for PDF based on specification details
 * @param {string} phase - SDLC phase
 * @param {string} type - Document type ('single' or 'combined')
 * @param {string} projectName - Optional project name
 * @returns {string} Generated filename
 */
export const generatePDFFilename = (phase, type = 'single', projectName = null) => {
  const timestamp = new Date().toISOString().slice(0, 19).replace(/[:-]/g, '');
  const project = projectName ? `${projectName}_` : '';
  
  if (type === 'combined') {
    return `${project}combined_specifications_${timestamp}.pdf`;
  } else {
    return `${project}${phase}_specification_${timestamp}.pdf`;
  }
};

/**
 * Validate PDF generation options
 * @param {Object} options - Options to validate
 * @returns {Object} Validated options
 */
export const validatePDFOptions = (options = {}) => {
  const validatedOptions = {
    includeBranding: options.includeBranding !== false,
    includeHeaders: options.includeHeaders !== false,
    includeFooters: options.includeFooters !== false,
    pageSize: ['letter', 'a4'].includes(options.pageSize) ? options.pageSize : 'letter'
  };

  return validatedOptions;
};

/**
 * Check if PDF generation is supported in the current browser
 * @returns {boolean} True if supported
 */
export const isPDFGenerationSupported = () => {
  return typeof Blob !== 'undefined' && typeof URL !== 'undefined' && typeof URL.createObjectURL === 'function';
};

/**
 * Get PDF generation status message
 * @param {string} phase - SDLC phase
 * @param {string} status - Generation status
 * @returns {string} Status message
 */
export const getPDFGenerationStatusMessage = (phase, status) => {
  const phaseTitle = phase.charAt(0).toUpperCase() + phase.slice(1);
  
  switch (status) {
    case 'generating':
      return `Generating ${phaseTitle} specification PDF...`;
    case 'success':
      return `${phaseTitle} specification PDF generated successfully`;
    case 'error':
      return `Failed to generate ${phaseTitle} specification PDF`;
    default:
      return `Processing ${phaseTitle} specification PDF...`;
  }
};

/**
 * Generate PDF from JSON specification content using Claude AI
 * @param {string} projectId - Project ID
 * @param {Object} specification - JSON specification content
 * @param {string} phase - SDLC phase
 * @param {string} projectName - Project name (optional)
 * @param {Object} options - Generation options
 * @returns {Promise<Blob>} PDF blob data
 */
export const generatePDFFromJSONSpecification = async (projectId, specification, phase, projectName = null, options = {}) => {
  try {
    console.log('🔄 Generating PDF from JSON specification using Claude AI...');
    
    const requestBody = {
      specification: specification,
      phase: phase,
      project_name: projectName || projectId,
      ...options
    };

    console.log('📤 Sending JSON specification PDF request:', {
      projectId,
      phase,
      projectName: projectName || projectId,
      specificationKeys: Object.keys(specification)
    });

    // Make the API call to generate PDF from JSON specification
    const apiConfig = getApiConfig();
    const authHeader = await authService.getAuthHeader();
    
    const response = await fetch(`${apiConfig.baseUrl}/api/pdfs/${projectId}/generate-from-json`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/pdf',
        ...(authHeader && { 'Authorization': authHeader })
      },
      body: JSON.stringify(requestBody),
      credentials: 'include'
    });
    
    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`PDF generation failed: ${response.status} ${response.statusText} - ${errorText}`);
    }
    
    // The response should be the PDF blob directly
    const pdfBlob = await response.blob();
    
    if (pdfBlob.size === 0) {
      throw new Error('Received empty PDF response');
    }
    
    console.log('✅ JSON specification PDF generated successfully');
    return pdfBlob;
    
  } catch (error) {
    console.error('❌ JSON specification PDF generation failed:', error);
    throw error;
  }
};

/**
 * Generate filename for JSON specification PDF
 * @param {string} phase - SDLC phase
 * @param {string} projectName - Project name
 * @returns {string} Generated filename
 */
export const generateJSONSpecificationPDFFilename = (phase, projectName = 'project') => {
  const timestamp = new Date().toISOString().slice(0, 19).replace(/[:-]/g, '');
  const sanitizedProjectName = projectName.replace(/[^a-zA-Z0-9]/g, '_').toLowerCase();
  return `${sanitizedProjectName}_${phase}_specification_${timestamp}.pdf`;
};